import {MORNING_SCRIPT,VOICE_SAMPLE,englishVoices,selectEnglishVoice,speechRate} from './morning-core.mjs';
import {demoScene} from './demo-art.mjs';
const $=q=>document.querySelector(q),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PREF_KEY='harupoom-english-voice-v1';let voices=[],chosenURI='',rate=1,run=0,playing=false,utterance=null,startTimer=null;
try{const p=JSON.parse(localStorage.getItem(PREF_KEY)||'null');if(p&&typeof p.voiceURI==='string')chosenURI=p.voiceURI;if(p?.rate)rate=speechRate(p.rate);}catch{}
const supported=()=>typeof window.speechSynthesis!=='undefined'&&typeof window.SpeechSynthesisUtterance==='function';
function status(message,error=false){$('#voice-status').textContent=message;$('#voice-status').dataset.error=String(error);}
function savePreference(){try{localStorage.setItem(PREF_KEY,JSON.stringify({voiceURI:chosenURI,rate}));}catch{status('Voice selected for this visit only. Browser storage is unavailable.');}}
function render(){document.documentElement.dataset.skin='ivory';$('#morning-app').innerHTML=`<div class="morning-shell"><header class="morning-header"><a href="./demo.html">HaruPoom</a><span class="source-badge">Fictional story · Tap-to-play voice</span></header><section class="morning-hero"><div><span class="morning-clock">THE NEXT MORNING / STAGED SCENARIO</span><h1>You haven’t caught up.<br>You’re not alone.</h1><p class="lead">Grandma shared the nursery notice, daily note and a drawing last evening, while you were working late.<br>Now, start with what needs your attention.</p></div>${demoScene({condition:'rain',temperature:17,season:'autumn',source:'sample',severe:false})}</section><div class="morning-grid"><div><section class="morning-panel"><span class="eyebrow">A CALMER FIRST MINUTE</span><h2>Your morning, in a few words.</h2><p class="voice-detail">Scripted English preview · Device speech, not Meta output.<br>Audio starts only when you tap Play. It does not wake your phone or run in the background.</p><div class="voice-controls"><label>English voice<select id="voice-choice" aria-label="English voice"><option>Checking available voices…</option></select></label><label>Reading pace<select id="voice-rate" aria-label="Reading pace"><option value="0.94" ${rate===0.94?'selected':''}>Gentle</option><option value="1" ${rate===1?'selected':''}>Natural pace</option><option value="1.06" ${rate===1.06?'selected':''}>A little brisker</option></select></label></div><div class="morning-buttons"><button class="button primary" data-action="play" id="voice-play">▶ Play morning preview</button><button class="button quiet" data-action="stop" id="voice-stop" disabled>Stop</button></div><p class="voice-status" id="voice-status" role="status" aria-live="polite">Choose an English voice, then tap Play.</p><div class="voice-secondary"><button class="text-button" data-action="sample" id="voice-sample">Listen to a short sample</button><button class="text-button" data-action="refresh">Refresh voices</button></div><p class="voice-detail" id="voice-provider">Naturalness depends on your device’s installed English voices. No new paid service is connected.</p><details><summary>Read the exact spoken script</summary><ol class="voice-transcript">${MORNING_SCRIPT.map((line,i)=>`<li id="voice-line-${i}">${esc(line)}</li>`).join('')}</ol></details><a class="button primary morning-link" href="./demo.html#today">Open the morning app →</a><p class="caption">The app opens a separate interactive sample. This briefing never marks an item packed, pays a fee, or sends a family message.</p></section><section class="morning-panel"><span class="eyebrow">WHAT STILL NEEDS A HUMAN CHECK</span><h2>Bought isn’t packed.</h2><div class="source-bundle"><article><h3>Colored paper + glue</h3><p>In the fictional story, your partner bought them after the notice changed. Packing has not been confirmed.</p><span class="tag">PARTNER REPORT / NOT A PACKING CONFIRMATION</span></article><article><h3>One newly requested apron</h3><p>Check the updated notice and the actual bag.</p><span class="tag">REVIEW BEFORE CONFIRMING</span></article><article><h3>Activity fee</h3><p>Payment is unconfirmed in this story. A request to your partner would need your review. No payment or request is performed here.</p><span class="tag">NO MONEY MOVED / NOTHING SENT</span></article></div><a class="button soft morning-link" href="./demo.html#source">Review the fictional notice →</a></section></div><aside><section class="morning-panel"><span class="eyebrow">LAST EVENING / FICTIONAL FAMILY BUNDLE</span><h2>What Grandma left for you.</h2><div class="source-bundle"><article><h3>Nursery notice</h3><p>Tomorrow’s art class starts at 9:30 a.m. Colored paper, glue and an apron need to go in the bag.</p><span class="tag">STAGED NOTICE / NOT FETCHED FROM AN APP</span></article><article><h3>A daily note</h3><p>“We made an autumn tree with colored paper.” This is an authored example, not a statement about a real child.</p><span class="tag">FICTIONAL RECORD / NO FEELINGS INFERRED</span></article></div><div class="drawing-card"><svg viewBox="0 0 250 190" role="img" aria-label="Illustrative autumn tree, not an uploaded child’s drawing"><rect x="20" y="10" width="210" height="170" rx="6" fill="#fffaf0" transform="rotate(-3 125 95)"/><path d="M121 85v64m0-32-30-25m30 12 29-27" stroke="#b69a70" stroke-width="9" stroke-linecap="round"/><path d="m67 69 29-20 27 30-27 24Z" fill="#ddb878"/><path d="m110 45 29-13 23 30-32 25Z" fill="#d8a189"/><path d="m151 72 25-12 17 31-31 15Z" fill="#b4bc8d"/><path d="m101 91 23-14 19 24-23 20Z" fill="#dec487"/><path d="M63 157q61-10 125 0" stroke="#c5cba9" fill="none" stroke-width="4"/></svg><p>Illustrative drawing stand-in<br>Not a photo upload or a real child’s artwork</p></div><p class="voice-detail">The drawing was already included in Grandma’s evening bundle in this story. It is not presented as a newly discovered morning upload.</p><details><summary>Pickup and care-note boundary</summary><p class="voice-detail">Grandma is the pickup person in the fictional scenario. Any clinic or medication note would be checked separately against its original source. This audio does not infer a diagnosis, read a dose, or recommend treatment.</p></details></section><section class="morning-panel"><span class="eyebrow">ONE LITTLE MOMENT ON THE WAY</span><h2>“What is the rain saying?”</h2><p class="voice-detail">The rain is a sample scenario, not a live forecast. Explore the boots, umbrella and safe 30-second experience in the app.</p><a class="button soft morning-link" href="./demo.html#today">See the rainy-morning cards →</a></section></aside></div><section class="morning-panel"><details><summary>Planned next steps · Not implemented in this voice preview</summary><ul class="about-list"><li><b>Meta server analysis:</b> analyze approved notice images with source quotations, then ask the caregiver to verify them.</li><li><b>User-controlled voice timing:</b> a schedule the user chooses, with notification permission, quiet hours and a clear off switch. This preview only plays after a tap.</li><li><b>Authenticated family sync:</b> explicit sharing permissions, separate accounts and verified delivery. Current family views stay on one device.</li><li><b>A separate weather source:</b> region selection, source attribution, updated time and manual fallback. The model should not invent the forecast.</li></ul></details></section><footer class="morning-footer">Prototype boundaries: fictional family history, scripted narration and sample weather. No automatic sharing, notifications, Meta model call, live weather, payment or treatment action. Voice quality and availability vary by device. Some operating-system voices use an online provider to read this non-personal script.</footer></div>`;refreshVoices();}
function refreshVoices(){if(!supported()){voices=[];$('#voice-choice').innerHTML='<option>No device speech support</option>';$('#voice-play').disabled=true;$('#voice-sample').disabled=true;status('This browser does not support device speech. The exact English script is available below.',true);return;}voices=englishVoices(window.speechSynthesis.getVoices());const selected=selectEnglishVoice(voices,chosenURI);chosenURI=selected?.voiceURI||'';$('#voice-choice').innerHTML=voices.length?voices.map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===chosenURI?'selected':''}>${esc(v.name)} (${esc(v.lang)})${v.localService?' · on device':' · provider voice'}</option>`).join(''):'<option>No English voices available yet</option>';$('#voice-play').disabled=!voices.length||playing;$('#voice-sample').disabled=!voices.length||playing;$('#voice-choice').disabled=playing;$('#voice-rate').disabled=playing;if(!playing)status(voices.length?'Ready. Tap Play to hear this fictional morning.':'No English voice is available yet. Try Refresh voices or an installed English voice on your device.',!voices.length);providerNote();}
function providerNote(){const voice=voices.find(v=>v.voiceURI===chosenURI);$('#voice-provider').textContent=voice?`${voice.name} · ${voice.localService?'reported by the browser as on-device':'provider voice; it may use an online speech service'}. Naturalness varies by device. This is not a Meta-generated voice.`:'Naturalness depends on your installed English voices. No paid voice service has been connected.';}
function stopSpeech(message='Stopped. Nothing in the preparation checklist changed.'){run++;playing=false;clearTimeout(startTimer);if(supported())window.speechSynthesis.cancel();utterance=null;$('#voice-stop').disabled=true;document.querySelectorAll('.voice-transcript li').forEach(n=>n.classList.remove('current'));refreshVoices();status(message);}
function playSpeech(sample=false){if(playing)return;refreshVoices();const voice=voices.find(v=>v.voiceURI===chosenURI);if(!supported()||!voice){status('Choose an available English voice first. The script stays readable below.',true);return;}const token=++run;window.speechSynthesis.cancel();playing=true;$('#voice-play').disabled=true;$('#voice-sample').disabled=true;$('#voice-choice').disabled=true;$('#voice-rate').disabled=true;$('#voice-stop').disabled=false;status('Starting the English voice…');const lines=sample?[VOICE_SAMPLE]:MORNING_SCRIPT;function say(index){if(token!==run)return;if(index===lines.length){playing=false;utterance=null;$('#voice-stop').disabled=true;refreshVoices();status(sample?'Sample finished. Choose another English voice or play the full preview.':'Preview finished. Open the app when you’re ready. No records were changed.');return;}utterance=new window.SpeechSynthesisUtterance(lines[index]);utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=rate;utterance.pitch=1;utterance.volume=1;utterance.onstart=()=>{if(token!==run)return;clearTimeout(startTimer);status(sample?'Playing the English voice sample.':`Playing the fictional briefing · ${index+1} of ${lines.length}`);if(!sample){document.querySelectorAll('.voice-transcript li').forEach(n=>n.classList.remove('current'));$('#voice-line-'+index)?.classList.add('current');}};utterance.onend=()=>{if(token!==run)return;clearTimeout(startTimer);say(index+1);};utterance.onerror=e=>{if(token!==run)return;stopSpeech();status('The device could not play that voice. Try another English voice and check media volume. The script is still available.',true);};startTimer=setTimeout(()=>{if(token!==run)return;stopSpeech();status('Playback did not start. Try another installed English voice, then tap Play again.',true);},10000);try{window.speechSynthesis.speak(utterance);}catch{stopSpeech();status('This English voice could not start. Try another voice or read the transcript.',true);}}say(0);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case 'play':playSpeech(false);break;case 'sample':playSpeech(true);break;case 'stop':stopSpeech();break;case 'refresh':if(!playing)refreshVoices();break;}});
document.addEventListener('change',e=>{if(e.target.id==='voice-choice'){chosenURI=e.target.value;savePreference();providerNote();}if(e.target.id==='voice-rate'){try{rate=speechRate(e.target.value);savePreference();}catch(err){status(err.message,true);}}});
window.addEventListener('pagehide',()=>stopSpeech('Playback stopped when you left this page.'));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing)stopSpeech('Playback stopped when this page was hidden. Tap Play to start again.');});
render();if(supported()){if(window.speechSynthesis.addEventListener)window.speechSynthesis.addEventListener('voiceschanged',refreshVoices);else window.speechSynthesis.onvoiceschanged=refreshVoices;}
